/* 
  LIVE CODING CHALLENGE:
  "Write a function that executes an array of asynchronous tasks, 
  but only runs exactly 2 tasks at a time (Concurrency Limiter)."
*/

async function limitConcurrency(tasks, limit) {
  const results = [];
  const executing = [];

  for (const task of tasks) {
    // Start the task
    const p = task().then(res => {
      // When finished, remove it from the 'executing' array
      executing.splice(executing.indexOf(p), 1);
      return res;
    });

    results.push(p);
    executing.push(p);

    // If we hit the limit, pause the loop until at least ONE task finishes
    if (executing.length >= limit) {
      await Promise.race(executing);
    }
  }

  return Promise.all(results);
}

